function searchModal(){$('#modal').innerHTML='<div class="modal-head"><h2>Find your next thread.</h2><button class="icon-button" data-do="close-modal" aria-label="Close">×</button></div><input id="search-field" type="search" placeholder="Projects, agents, conversations…" aria-label="Search workspace"><div id="search-results"></div>';$('#modal').showModal();$('#search-field').focus();searchResults('');}
function searchResults(q){q=q.toLowerCase();const items=[...W.state.projects.map(p=>({name:p.name,type:'Project',id:p.id})),...W.state.workers.map(w=>({name:w.name,type:'Agent',view:'workers'})),...W.state.conversations.map(c=>({name:c.title,type:'Conversation',view:'chat',conversationId:c.id}))].filter(x=>x.name.toLowerCase().includes(q)).slice(0,12);$('#search-results').innerHTML=items.map(x=>`<button class="search-result" ${x.type==='Project'?`data-project="${x.id}"`:`data-nav="${x.view}"`}><span>${esc(x.name)}</span><small>${x.type}</small></button>`).join('')||'<p class="muted">No matches yet.</p>';}
document.addEventListener('click',e=>{if(e.target.closest('.search-result'))$('#modal').close();});
